-- External audit fixes 2026-10-13 - ROLLBACK (restore previous published versions)
-- generated by scripts/prod-open/sat-manual-patches-sql.ts. Non-production target only (worpsqwqgnspddnrtnvq). One DO block = one transaction: any failure rolls everything back.
-- problems: 17 new problem versions, sets: 0 new set versions (draft -> validate -> publish; previous version archived; access tier inherited).
-- Run (coordinator): npx supabase db query --linked -f <this file>

do $audit$
declare
  v_rb constant jsonb := $audit_plan${"problems":[{"patch_id":"E1019-M001","problem_id":"01d7207e-c5d8-4b93-a2ea-ba5b57b7ff0e","from_version_id":"78d5b304-f76c-4a00-9cc3-43c8bdcd223f"},{"patch_id":"E1019-M002","problem_id":"079d2fb7-55f3-455f-a32c-32b252e0da59","from_version_id":"340e0200-5521-439a-a0a6-c963b2facbb1"},{"patch_id":"E1019-M003","problem_id":"0b94e63d-1d30-4fdb-ad23-2ea8895e0978","from_version_id":"40cdedc9-ee3d-449c-a70f-a7acb7022511"},{"patch_id":"E1019-M004","problem_id":"1473eff6-7ef8-48a6-add7-d241754fdec6","from_version_id":"38f78fff-5fc5-425b-aa46-9fdee6c50071"},{"patch_id":"E1019-M005","problem_id":"2c4d3a89-40e8-4de9-9d80-7d91657c2674","from_version_id":"c230feb0-5c39-4c1d-b8cc-1001fc1f84db"},{"patch_id":"E1019-M006","problem_id":"c93ba362-8516-4e33-b085-ce1b5615787d","from_version_id":"7b28c320-4ffa-4f5e-8f79-8642177a9cb8"},{"patch_id":"E1019-M007","problem_id":"dcea79ab-0a4c-4923-8c01-21b87e30d90d","from_version_id":"3c7dabf8-6927-4cd9-b3f7-d3972af93f37"},{"patch_id":"E1019-M008","problem_id":"eaac2a72-9970-466d-b509-1c34b9b80a26","from_version_id":"fcbdf235-11b3-4f95-a8e1-9da30dcac1ce"},{"patch_id":"E1019-M009","problem_id":"58c8d686-47e7-4ce7-95fe-ebfda36d4e60","from_version_id":"01a885fa-75cb-4c49-8fe7-a491e8388ebf"},{"patch_id":"E1019-M010","problem_id":"2d39235f-33fc-44e9-9945-777c44395d5a","from_version_id":"a60926e9-e94e-4b4c-b147-a1f7c64105e6"},{"patch_id":"E1019-M011","problem_id":"3cdc0ad5-a948-4e18-9906-a91e90334fdb","from_version_id":"fe49203e-f7c8-4f44-8a5b-be6a6d16b5e2"},{"patch_id":"E1019-M012","problem_id":"4cc47e7c-e766-47d8-aa9b-ae16aeb96d71","from_version_id":"aba6ad73-82bb-4792-a396-79ea26f18f33"},{"patch_id":"E1019-M013","problem_id":"e90ca1b1-6000-4e2d-9346-c6f757d5bed7","from_version_id":"54097df7-5ae6-49a8-8b49-870ee0237835"},{"patch_id":"E1019-M014","problem_id":"9977438d-6d27-48ed-aebb-c4ad8e08c6c0","from_version_id":"af1907f7-c7e6-445b-aecb-b3947e37410f"},{"patch_id":"E1019-M015","problem_id":"e1f8fcfb-fbe0-45e7-819a-a38851a50e39","from_version_id":"6c7a5e80-bad9-4440-a697-7691f27e43b7"},{"patch_id":"E1019-M016","problem_id":"f59b7f57-b596-4235-9902-d8036d9040ff","from_version_id":"35ba1e3b-847b-4fd0-81d1-84be51f51d15"},{"patch_id":"E1019-M017","problem_id":"d1e251f0-cebc-4187-b79c-37da71685423","from_version_id":"087c1c2c-ceb6-4207-9e2d-bfa4f88d8ccc"}],"sets":[]}$audit_plan$::jsonb;
  v_actor uuid := (select id from profiles where role = 'admin' order by created_at limit 1);
  u jsonb; s jsonb; v_new uuid; v_old problem_versions%rowtype; v_n int := 0;
begin
  -- Problems first (the set publish gate needs each item's version to be the problem's current published version).
  for u in select * from jsonb_array_elements(v_rb->'problems') loop
    select id into v_new from problem_versions where problem_id = (u->>'problem_id')::uuid and status = 'published' and quality->'auditFix'->>'patch' = u->>'patch_id';
    if v_new is null then raise notice '[%] no audit version is published, skipped', u->>'patch_id'; continue; end if;
    select * into v_old from problem_versions where id = (u->>'from_version_id')::uuid;
    if v_old.id is null then raise exception '[%] previous version missing', u->>'patch_id'; end if;
    update problem_versions set status = 'archived' where id = v_new;
    update problem_versions set status = 'published' where id = v_old.id;
    update problems set passage = v_old.passage, options = v_old.options, correct_index = v_old.correct_index, explanation = v_old.explanation, published_version_id = v_old.id where id = v_old.problem_id;
    if u ? 'ap' then perform public.ap_attach_new_version(u->'ap'->>'candidate_key', (u->'ap'->>'item_index')::int, v_old.id, v_actor); end if;
    v_n := v_n + 1;
  end loop;
  -- Sets: archive the version created by the audit, republish the previous one (only when a newer version than the previous exists).
  for s in select * from jsonb_array_elements(v_rb->'sets') loop
    if exists (select 1 from mock_exam_sets n where n.set_group_id = (s->>'set_group_id')::uuid and n.status = 'published' and n.id <> (s->>'set_id')::uuid) then
      update mock_exam_sets set status = 'archived', archived_at = now() where set_group_id = (s->>'set_group_id')::uuid and status = 'published' and id <> (s->>'set_id')::uuid;
      update mock_exam_sets set status = 'published', archived_at = null, published_at = (s->>'published_at')::timestamptz, published_by = (s->>'published_by')::uuid, access_tier = coalesce(s->>'access_tier', access_tier)
       where id = (s->>'set_id')::uuid;
    end if;
  end loop;
  raise notice 'ROLLBACK DONE problems restored=%', v_n;
end
$audit$;
